[
  {
    "name": "clarify_language",
    "agent": "researcher",
    "prompt": "Determine the programming language required for the linear search code generation by interacting with the user.",
    "deps": []
  },
  {
    "name": "generate_code",
    "agent": "coder",
    "prompt": "Generate the code for the linear search algorithm in the language specified by the user.",
    "deps": ["clarify_language"]
  },
  {
    "name": "review_code",
    "agent": "critic",
    "prompt": "Review the generated code for best practices, readability, and efficiency.",
    "deps": ["generate_code"]
  },
  {
    "name": "validate_code",
    "agent": "validator",
    "prompt": "Validate that the generated code meets the user's requirements and is functional.",
    "deps": ["review_code"]
  },
  {
    "name": "optimize_code",
    "agent": "optimizer",
    "prompt": "Optimize the code for performance, if necessary, based on user feedback or requirements.",
    "deps": ["validate_code"]
  },
  {
    "name": "report_results",
    "agent": "reporter",
    "prompt": "Provide the final code and any relevant analysis or reviews to the user, ensuring it meets their expectations.",
    "deps": ["optimize_code"]
  }
]

[
  {
    "name": "select_algorithm",
    "agent": "researcher",
    "prompt": "Select the appropriate binary search algorithm and provide a high-level outline of the steps involved.",
    "deps": []
  },
  {
    "name": "generate_code",
    "agent": "coder",
    "prompt": "Generate the code for the binary search algorithm in a specified programming language based on the selected algorithm.",
    "deps": ["select_algorithm"]
  },
  {
    "name": "optimize_code",
    "agent": "optimizer",
    "prompt": "Refine the generated code to improve performance, readability, or adherence to specific coding standards.",
    "deps": ["generate_code"]
  },
  {
    "name": "validate_code",
    "agent": "validator",
    "prompt": "Verify that the generated code is correct, functional, and meets the requirements of the binary search algorithm.",
    "deps": ["optimize_code"]
  },
  {
    "name": "document_code",
    "agent": "analyst",
    "prompt": "Create documentation or comments explaining how the code works, including any assumptions made or limitations of the implementation.",
    "deps": ["validate_code"]
  },
  {
    "name": "test_code",
    "agent": "critic",
    "prompt": "Create test cases or example usage to demonstrate the correctness and functionality of the generated code.",
    "deps": ["document_code"]
  }
]

[
  {
    "name": "clarify_concept",
    "agent": "researcher",
    "prompt": "Interact with the user to gather more context about the subject of interest and identify the specific concept or technology the user is referring to.",
    "deps": []
  },
  {
    "name": "gather_relevant_info",
    "agent": "researcher",
    "prompt": "Gather relevant information about the clarified concept, including its definition, applications, and potential use cases.",
    "deps": ["clarify_concept"]
  },
  {
    "name": "analyze_use_cases",
    "agent": "analyst",
    "prompt": "Process the retrieved information to identify and categorize the most relevant and practical use cases.",
    "deps": ["gather_relevant_info"]
  },
  {
    "name": "generate_output",
    "agent": "optimizer",
    "prompt": "Create a concise and well-structured output, presenting the use cases in a clear and actionable format.",
    "deps": ["analyze_use_cases"]
  },
  {
    "name": "validate_output",
    "agent": "validator",
    "prompt": "Review the generated output to ensure it meets the requirements and is accurate, complete, and relevant.",
    "deps": ["generate_output"]
  },
  {
    "name": "report_findings",
    "agent": "reporter",
    "prompt": "Present the final output, including a brief introduction to the concept, a categorized list of use cases, examples, and recommendations for further exploration.",
    "deps": ["validate_output"]
  }
]

[
  {
    "name": "gather_machine_learning_info",
    "agent": "researcher",
    "prompt": "search the knowledge base for relevant information on machine learning, including definitions, key concepts, and applications",
    "deps": []
  },
  {
    "name": "generate_machine_learning_text",
    "agent": "coder",
    "prompt": "create a clear and concise response that explains machine learning in an easy-to-understand manner based on the gathered information",
    "deps": ["gather_machine_learning_info"]
  },
  {
    "name": "refine_machine_learning_text",
    "agent": "analyst",
    "prompt": "refine the output, ensuring that it is engaging, well-structured, and free of errors",
    "deps": ["generate_machine_learning_text"]
  },
  {
    "name": "validate_machine_learning_text",
    "agent": "validator",
    "prompt": "validate the refined text to ensure it meets the expected output requirements",
    "deps": ["refine_machine_learning_text"]
  },
  {
    "name": "report_machine_learning_info",
    "agent": "reporter",
    "prompt": "format the validated text into a clear and concise introduction to machine learning, including a definition, key concepts, examples of applications, and benefits and limitations",
    "deps": ["validate_machine_learning_text"]
  },
  {
    "name": "finalize_machine_learning_output",
    "agent": "optimizer",
    "prompt": "finalize the output to provide a solid foundation for further learning and exploration",
    "deps": ["report_machine_learning_info"]
  }
]

[
  {
    "name": "analyze_quick_sort",
    "agent": "researcher",
    "prompt": "Provide a detailed explanation of the quick sort algorithm, including its logic, time complexity, and any relevant variations.",
    "deps": []
  },
  {
    "name": "choose_programming_language",
    "agent": "analyst",
    "prompt": "Help determine the target programming language for the quick sort implementation, considering popular options like Python, Java, or C++.",
    "deps": ["analyze_quick_sort"]
  },
  {
    "name": "generate_quick_sort_code",
    "agent": "coder",
    "prompt": "Generate the quick sort code based on the provided algorithm specifications and chosen programming language.",
    "deps": ["choose_programming_language"]
  },
  {
    "name": "review_code_quality",
    "agent": "critic",
    "prompt": "Evaluate the generated code's readability, maintainability, and efficiency to ensure it meets the user's expectations.",
    "deps": ["generate_quick_sort_code"]
  },
  {
    "name": "optimize_code",
    "agent": "optimizer",
    "prompt": "Refine the generated code for better performance, readability, or maintainability, if requested by the user.",
    "deps": ["review_code_quality"]
  },
  {
    "name": "validate_output",
    "agent": "validator",
    "prompt": "Verify that the final output meets the user's requirements and is a well-structured, readable, and functional implementation of the quick sort algorithm.",
    "deps": ["optimize_code"]
  }
]

[
  {
    "name": "load_sales_data",
    "agent": "coder",
    "prompt": "Load the sales.csv file into the system, handling any initial data cleaning or formatting issues.",
    "deps": []
  },
  {
    "name": "explore_sales_data",
    "agent": "analyst",
    "prompt": "Perform preliminary data analysis, including summary statistics, data distribution analysis, and identification of missing or erroneous data.",
    "deps": ["load_sales_data"]
  },
  {
    "name": "transform_sales_data",
    "agent": "coder",
    "prompt": "Transform the data into a more suitable format for analysis, handling tasks such as data normalization or feature scaling.",
    "deps": ["explore_sales_data"]
  },
  {
    "name": "analyze_sales_data",
    "agent": "analyst",
    "prompt": "Conduct in-depth statistical analysis, including regression, correlation analysis, and hypothesis testing, to uncover trends and patterns in the sales data.",
    "deps": ["transform_sales_data"]
  },
  {
    "name": "visualize_sales_insights",
    "agent": "reporter",
    "prompt": "Create visual representations of the findings, such as plots, charts, and heatmaps, to facilitate understanding and communication of the results.",
    "deps": ["analyze_sales_data"]
  },
  {
    "name": "generate_insight_report",
    "agent": "reporter",
    "prompt": "Generate a narrative summary of the key findings, including any identified trends, patterns, or correlations, along with recommendations for future actions based on the analysis.",
    "deps": ["visualize_sales_insights"]
  }
]

[
  {
    "name": "gather_requirements",
    "agent": "researcher",
    "prompt": "Gather requirements and define the application's functional and non-functional needs, considering factors such as database design, server infrastructure, API integration, security, and scalability.",
    "deps": []
  },
  {
    "name": "design_high_level_architecture",
    "agent": "analyst",
    "prompt": "Design a high-level backend architecture, considering scalability, performance, and security, based on the gathered requirements.",
    "deps": ["gather_requirements"]
  },
  {
    "name": "design_database_schema",
    "agent": "analyst",
    "prompt": "Design a suitable database schema and recommend a database management system, aligned with the high-level architecture.",
    "deps": ["design_high_level_architecture"]
  },
  {
    "name": "plan_server_infrastructure",
    "agent": "optimizer",
    "prompt": "Plan the server infrastructure, including cloud services, containerization, and orchestration, to support the designed architecture.",
    "deps": ["design_database_schema"]
  },
  {
    "name": "ensure_security_and_compliance",
    "agent": "critic",
    "prompt": "Ensure the architecture is secure, compliant with relevant standards, and protected against potential threats, and provide a security plan and compliance report.",
    "deps": ["plan_server_infrastructure"]
  },
  {
    "name": "validate_architecture_design",
    "agent": "validator",
    "prompt": "Review and validate the generated architecture against the user's requirements and industry best practices, and provide a validated architecture design.",
    "deps": ["ensure_security_and_compliance"]
  }
]

[
  {
    "name": "define_requirements",
    "agent": "researcher",
    "prompt": "Identify the scalability requirements of the application, including expected traffic, user base, and data storage needs.",
    "deps": []
  },
  {
    "name": "evaluate_frameworks",
    "agent": "researcher",
    "prompt": "Research and evaluate popular backend frameworks for scalability, such as Node.js, Django, or Flask, considering factors like performance, security, and maintainability.",
    "deps": ["define_requirements"]
  },
  {
    "name": "design_architecture",
    "agent": "researcher",
    "prompt": "Based on the evaluated frameworks, design a scalable backend architecture that meets the application's requirements, including database schema, API endpoints, and caching strategies.",
    "deps": ["evaluate_frameworks"]
  },
  {
    "name": "implement_solution",
    "agent": "coder",
    "prompt": "Implement the designed backend architecture using the chosen framework, ensuring code quality, security, and scalability.",
    "deps": ["design_architecture"]
  }
]

[
  {
    "name": "ingest_sales_data",
    "agent": "researcher",
    "prompt": "Retrieve sales data from relevant databases or data sources",
    "deps": []
  },
  {
    "name": "filter_north_region",
    "agent": "researcher",
    "prompt": "Filter retrieved data by the North region",
    "deps": ["ingest_sales_data"]
  },
  {
    "name": "analyze_revenue",
    "agent": "researcher",
    "prompt": "Analyze filtered data to identify the product with the highest revenue",
    "deps": ["filter_north_region"]
  },
  {
    "name": "format_result",
    "agent": "reporter",
    "prompt": "Format the result into a user-friendly output",
    "deps": ["analyze_revenue"]
  }
]

[
  {
    "name": "ingest_sales_data",
    "agent": "researcher",
    "prompt": "Ingest the 'sales.csv' file and retrieve its contents",
    "deps": []
  },
  {
    "name": "process_revenue_data",
    "agent": "coder",
    "prompt": "Process the ingested data, extract relevant information (e.g., product names, revenue), and perform data analysis to identify the product with the highest revenue",
    "deps": ["ingest_sales_data"]
  },
  {
    "name": "validate_analysis_results",
    "agent": "validator",
    "prompt": "Verify the accuracy and completeness of the analysis results",
    "deps": ["process_revenue_data"]
  },
  {
    "name": "generate_report",
    "agent": "reporter",
    "prompt": "Generate a report summarizing the findings, including the product with the highest revenue",
    "deps": ["validate_analysis_results"]
  }
]

[
  {
    "name": "clarify_input",
    "agent": "parameter_agent",
    "prompt": "Clarify the input parameters, such as the ten numbers to be compared.",
    "deps": []
  },
  {
    "name": "design_comparison_logic",
    "agent": "logic_agent",
    "prompt": "Design the comparison logic and create a basic algorithm for finding the largest number.",
    "deps": ["clarify_input"]
  },
  {
    "name": "generate_code",
    "agent": "code_generation_agent",
    "prompt": "Generate the actual code in a chosen programming language based on the logic designed by the Logic Agent.",
    "deps": ["design_comparison_logic"]
  },
  {
    "name": "test_code",
    "agent": "testing_agent",
    "prompt": "Test the generated code with sample inputs to ensure it works correctly.",
    "deps": ["generate_code"]
  }
]
